mod cli;
mod desktop;
mod mimeapps;
mod mime_kind;
mod globs;
mod config;
mod exec;
mod open;
mod table;
mod url_util;
mod common;

use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    match cli::parse(&args) {
        Ok(cli::Invocation::Help) => {
            print!("{}", cli::TOP_HELP);
            ExitCode::from(0)
        }
        Ok(cli::Invocation::Version) => {
            println!("handlr 0.6.4");
            ExitCode::from(0)
        }
        Ok(cli::Invocation::Sub(sub)) => match run(sub) {
            Ok(()) => ExitCode::from(0),
            Err(e) => {
                eprintln!("Error: {}", e);
                ExitCode::from(1)
            }
        },
        Err(cli::CliError::UsageTop) => {
            print!("{}", cli::TOP_HELP);
            ExitCode::from(0)
        }
        Err(e) => {
            eprintln!("{}", e);
            ExitCode::from(2)
        }
    }
}

fn run(sub: cli::Subcommand) -> Result<(), common::Error> {
    use cli::Subcommand::*;
    match sub {
        List { all } => cli::cmd_list(all),
        Open { paths } => open::cmd_open(&paths),
        Set { mime, handler } => cli::cmd_set(&mime, &handler),
        Unset { mime } => cli::cmd_unset(&mime),
        Add { mime, handler } => cli::cmd_add(&mime, &handler),
        Launch { mime, args } => cli::cmd_launch(&mime, &args),
        Get { mime, json } => cli::cmd_get(&mime, json),
    }
}
