pub enum Error {
    Io(std::io::Error),
    NotFound,
    MalformedDesktopEntry(String),
    Custom(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(e) => write!(f, "Io(Os {{ code: {}, kind: {:?}, message: {:?} }})",
