cat > src/cli.rs << 'EOF'
use std::fmt;
use crate::common::Error;
use crate::config;
use crate::desktop;
use crate::exec;
use crate::mime_kind::MimeOrExtension;
use crate::mimeapps;

pub const TOP_HELP: &str = "handlr 0.6.4

USAGE:
    executable <SUBCOMMAND>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

SUBCOMMANDS:
    list      List default apps and the associated handlers
    open      Open a path/URL with its default handler
    set       Set the default handler for mime/extension
    unset     Unset the default handler for mime/extension
    launch    Launch the handler for specified extension/mime with optional arguments
    get       Get handler for this mime/extension
    add       Add a handler for given mime/extension Note that the first handler is the default
";

const LIST_HELP: &str = "executable-list \nList default apps and the associated handlers\n\nUSAGE:\n    executable list [FLAGS]\n\nFLAGS:\n    -a, --all        \n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";
const OPEN_HELP: &str = "executable-open \nOpen a path/URL with its default handler\n\nUSAGE:\n    executable open <paths>...\n\nARGS:\n    <paths>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";
const SET_HELP: &str = "executable-set \nSet the default handler for mime/extension\n\nUSAGE:\n    executable set <mime> <handler>\n\nARGS:\n    <mime>       \n    <handler>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";
const UNSET_HELP: &str = "executable-unset \nUnset the default handler for mime/extension\n\nUSAGE:\n    executable unset <mime>\n\nARGS:\n    <mime>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";
const LAUNCH_HELP: &str = "executable-launch \nLaunch the handler for specified extension/mime with optional arguments\n\nUSAGE:\n    executable launch <mime> [args]...\n\nARGS:\n    <mime>       \n    <args>...    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";
const GET_HELP: &str = "executable-get \nGet handler for this mime/extension\n\nUSAGE:\n    executable get [FLAGS] <mime>\n\nARGS:\n    <mime>    \n\nFLAGS:\n        --json       \n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";
const ADD_HELP: &str = "executable-add \nAdd a handler for given mime/extension Note that the first handler is the default\n\nUSAGE:\n    executable add <mime> <handler>\n\nARGS:\n    <mime>       \n    <handler>    \n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n";

pub enum Invocation {
    Help,
    Version,
    Sub(Subcommand),
}

pub enum Subcommand {
    List { all: bool },
    Open { paths: Vec<String> },
    Set { mime: String, handler: String },
    Unset { mime: String },
    Add { mime: String, handler: String },
    Launch { mime: String, args: Vec<String> },
    Get { mime: String, json: bool },
}

pub enum CliError {
    UsageTop,
    Msg(String),
}

impl fmt::Display for CliError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CliError::UsageTop => write!(f, "{}", TOP_HELP),
            CliError::Msg(m) => write!(f, "{}", m),
        }
    }
}

fn err_msg(s: impl Into<String>) -> CliError {
    CliError::Msg(s.into())
}

pub fn parse(args: &[String]) -> Result<Invocation, CliError> {
    if args.len() < 2 {
        return Ok(Invocation::Help);
    }
    let sub = &args[1];
    match sub.as_str() {
        "-h" | "--help" => Ok(Invocation::Help),
        "-V" | "--version" => Ok(Invocation::Version),
        "list" => parse_list(&args[2..]),
        "open" => parse_open(&args[2..]),
        "set" => parse_set(&args[2..]),
        "unset" => parse_unset(&args[2..]),
        "launch" => parse_launch(&args[2..]),
        "get" => parse_get(&args[2..]),
        "add" => parse_add(&args[2..]),
        other => {
            let msg = format!(
                "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\
                 If you tried to supply `{}` as a PATTERN use `-- {}`\n\n\
                 USAGE:\n    executable <SUBCOMMAND>\n\n\
                 For more information try --help",
                other, other, other
            );
            Err(err_msg(msg))
        }
    }
}

fn unexpected(sub_usage: &str, arg: &str) -> CliError {
    err_msg(format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\
         If you tried to supply `{}` as a PATTERN use `-- {}`\n\n\
         USAGE:\n    {}\n\n\
         For more information try --help",
        arg, arg, arg, sub_usage
    ))
}

fn required(sub_usage: &str, missing: &[&str]) -> CliError {
    let mut msg = String::from("error: The following required arguments were not provided:\n");
    for m in missing {
        msg.push_str(&format!("    {}\n", m));
    }
    msg.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help", sub_usage));
    err_msg(msg)
}

fn parse_list(args: &[String]) -> Result<Invocation, CliError> {
    let mut all = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-a" | "--all" => all = true,
            "-h" | "--help" => { print!("{}", LIST_HELP); std::process::exit(0); }
            "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
            other => return Err(unexpected("executable list [FLAGS]", other)),
        }
        i += 1;
    }
    Ok(Invocation::Sub(Subcommand::List { all }))
}

fn parse_open(args: &[String]) -> Result<Invocation, CliError> {
    let mut paths: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if !end_opts {
            match a.as_str() {
                "--" => { end_opts = true; i += 1; continue; }
                "-h" | "--help" => { print!("{}", OPEN_HELP); std::process::exit(0); }
                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
            }
        }
        paths.push(a.clone());
        i += 1;
    }
    if paths.is_empty() {
        return Err(required("executable open <paths>...", &["<paths>..."]));
    }
    Ok(Invocation::Sub(Subcommand::Open { paths }))
}

fn parse_set(args: &[String]) -> Result<Invocation, CliError> {
    let mut positional: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if !end_opts {
            match a.as_str() {
                "--" => { end_opts = true; i += 1; continue; }
                "-h" | "--help" => { print!("{}", SET_HELP); std::process::exit(0); }
                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
            }
        }
        positional.push(a.clone());
        i += 1;
    }
    if positional.len() > 2 {
        return Err(unexpected("executable set <mime> <handler>", &positional[2]));
    }
    if positional.len() < 2 {
        let missing: Vec<&str> = if positional.is_empty() { vec!["<mime>", "<handler>"] } else { vec!["<handler>"] };
        return Err(required("executable set <mime> <handler>", &missing));
    }
    // Validate <mime>
    let mime = &positional[0];
    let handler = &positional[1];
    validate_mime_arg("executable set <mime> <handler>", mime)?;
    validate_handler_arg("executable set <mime> <handler>", handler)?;
    Ok(Invocation::Sub(Subcommand::Set { mime: mime.clone(), handler: handler.clone() }))
}

fn parse_unset(args: &[String]) -> Result<Invocation, CliError> {
    let mut positional: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if !end_opts {
            match a.as_str() {
                "--" => { end_opts = true; i += 1; continue; }
                "-h" | "--help" => { print!("{}", UNSET_HELP); std::process::exit(0); }
                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
            }
        }
        positional.push(a.clone());
        i += 1;
    }
    if positional.len() > 1 {
        return Err(unexpected("executable unset <mime>", &positional[1]));
    }
    if positional.is_empty() {
        return Err(required("executable unset <mime>", &["<mime>"]));
    }
    validate_mime_arg("executable unset <mime>", &positional[0])?;
    Ok(Invocation::Sub(Subcommand::Unset { mime: positional.remove(0) }))
}

fn parse_add(args: &[String]) -> Result<Invocation, CliError> {
    let mut positional: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if !end_opts {
            match a.as_str() {
                "--" => { end_opts = true; i += 1; continue; }
                "-h" | "--help" => { print!("{}", ADD_HELP); std::process::exit(0); }
                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
            }
        }
        positional.push(a.clone());
        i += 1;
    }
    if positional.len() > 2 {
        return Err(unexpected("executable add <mime> <handler>", &positional[2]));
    }
    if positional.len() < 2 {
        let missing: Vec<&str> = if positional.is_empty() { vec!["<mime>", "<handler>"] } else { vec!["<handler>"] };
        return Err(required("executable add <mime> <handler>", &missing));
    }
    validate_mime_arg("executable add <mime> <handler>", &positional[0])?;
    validate_handler_arg("executable add <mime> <handler>", &positional[1])?;
    Ok(Invocation::Sub(Subcommand::Add { mime: positional[0].clone(), handler: positional[1].clone() }))
}

fn parse_launch(args: &[String]) -> Result<Invocation, CliError> {
    let mut positional: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if !end_opts {
            match a.as_str() {
                "--" => { end_opts = true; i += 1; continue; }
                "-h" | "--help" => { print!("{}", LAUNCH_HELP); std::process::exit(0); }
                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
