pub fn parse(args: &[String]) -> Result<Invocation, CliError> {
    if args.len() < 2 {
        return Ok(Invocation::Help);
    }
    let sub = &args[1];
    match sub.as_str() {
        "-h" | "--help" => Ok(Invocation::Help),
        "-V" | "--version" => Ok(Invocation::Version),
        "list" => parse_list(&args[2..]),
        "open" => parse_open(&args[2..]),
        "set" => parse_set(&args[2..]),
        "unset" => parse_unset(&args[2..]),
        "launch" => parse_launch(&args[2..]),
        "get" => parse_get(&args[2..]),
        "add" => parse_add(&args[2..]),
        other => {
            let msg = format!(
                "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\
                 If you tried to supply `{}` as a PATTERN use `-- {}`\n\n\
                 USAGE:\n    executable <SUBCOMMAND>\n\n\
                 For more information try --help",
                other, other, other
            );
            Err(err_msg(msg))
        }
    }
}

fn unexpected(sub_usage: &str, arg: &str) -> CliError {
    err_msg(format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\
         If you tried to supply `{}` as a PATTERN use `-- {}`\n\n\
         USAGE:\n    {}\n\n\
         For more information try --help",
        arg, arg, arg, sub_usage
    ))
}

fn required(sub_usage: &str, missing: &[&str]) -> CliError {
    let mut msg = String::from("error: The following required arguments were not provided:\n");
    for m in missing {
        msg.push_str(&format!("    {}\n", m));
    }
    msg.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help", sub_usage));
    err_msg(msg)
}

fn parse_list(args: &[String]) -> Result<Invocation, CliError> {
    let mut all = false;
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-a" | "--all" => all = true,
            "-h" | "--help" => { print!("{}", LIST_HELP); std::process::exit(0); }
            "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
            other => return Err(unexpected("executable list [FLAGS]", other)),
        }
        i += 1;
    }
    Ok(Invocation::Sub(Subcommand::List { all }))
}

fn parse_open(args: &[String]) -> Result<Invocation, CliError> {
    let mut paths: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if !end_opts {
            match a.as_str() {
                "--" => { end_opts = true; i += 1; continue; }
                "-h" | "--help" => { print!("{}", OPEN_HELP); std::process::exit(0); }
                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
            }
        }
        paths.push(a.clone());
        i += 1;
    }
    if paths.is_empty() {
        return Err(required("executable open <paths>...", &["<paths>..."]));
    }
    Ok(Invocation::Sub(Subcommand::Open { paths }))
}

fn parse_set(args: &[String]) -> Result<Invocation, CliError> {
    let mut positional: Vec<String> = Vec::new();
    let mut end_opts = false;
    let mut i = 0;
