                "-V" | "--version" => { println!("handlr 0.6.4"); std::process::exit(0); }
                _ => {}
            }
        }
        positional.push(a.clone());
        i += 1;
    }
    if positional.len() > 2 {
        return Err(unexpected("executable set <mime> <handler>", &positional[2]));
    }
    if positional.len() < 2 {
        let missing: Vec<&str> = if positional.is_empty() { vec!["<mime>", "<handler>"] } else { vec!["<handler>"] };
        return Err(required("executable set <mime> <handler>", &missing));
    }
    // Validate <mime>
    let mime = &positional[0];
    let handler = &positional[1];
    validate_mime_arg("executable set <mime> <handler>", mime)?;
    validate_handler_arg("executable set <mime> <handler>", handler)?;
    Ok(Invocation::Sub(Subcommand::Set { mime: mime.clone(), handler: handler.clone() }))
}

