fn validate_mime_arg(usage: &str, v: &str) -> Result<(), CliError> {
    match MimeOrExtension::parse(v) {
        Ok(_) => Ok(()),
        Err(msg) => Err(err_msg(format!(
            "error: Invalid value for '<mime>': {}\n\nFor more information try --help",
            msg
        ))),
    }
}

fn validate_handler_arg(_usage: &str, v: &str) -> Result<(), CliError> {
    match desktop::validate_handler(v) {
        Ok(_) => Ok(()),
        Err(msg) => Err(err_msg(format!(
            "error: Invalid value for '<handler>': {}\n\nFor more information try --help",
            msg
        ))),
    }
}

// ---- Command implementations ----

pub fn cmd_list(all: bool) -> Result<(), Error> {
    let ma = mimeapps::MimeApps::load()?;
    if all {
        println!("Default Apps");
        let default: Vec<(String, Vec<String>)> = filter_valid(&ma.default_apps)?;
        crate::table::print_two_col(&default);
        if !ma.added_associations.is_empty() {
            let added: Vec<(String, Vec<String>)> = filter_valid(&ma.added_associations)?;
            if !added.is_empty() {
                println!("Added Associations");
                crate::table::print_two_col(&added);
            }
        }
        println!("System Apps");
        let system = system_apps_sorted()?;
        crate::table::print_two_col(&system);
    } else {
        let default = filter_valid(&ma.default_apps)?;
        crate::table::print_two_col(&default);
    }
    Ok(())
}

fn filter_valid(entries: &[(String, Vec<String>)]) -> Result<Vec<(String, Vec<String>)>, Error> {
    let mut out = Vec::new();
    for (k, v) in entries {
        let mut kept = Vec::new();
        for h in v {
            if desktop::exists(h) {
                kept.push(h.clone());
            }
        }
        if !kept.is_empty() {
            out.push((k.clone(), kept));
        }
    }
    Ok(out)
}

fn system_apps_sorted() -> Result<Vec<(String, Vec<String>)>, Error> {
    let sys = desktop::scan_system_mimes();
    let mut v: Vec<(String, Vec<String>)> = sys.into_iter().collect();
    v.sort_by(|a, b| a.0.cmp(&b.0));
    Ok(v)
}

pub fn cmd_set(mime: &str, handler: &str) -> Result<(), Error> {
    let mime = MimeOrExtension::parse(mime).unwrap();
    let mime_str = mime.to_mime_key()?;
    let mut ma = mimeapps::MimeApps::load()?;
    ma.set_default(&mime_str, handler);
    ma.save()?;
    Ok(())
}

pub fn cmd_unset(mime: &str) -> Result<(), Error> {
    let mime = MimeOrExtension::parse(mime).unwrap();
    let mime_str = mime.to_mime_key()?;
    let mut ma = mimeapps::MimeApps::load()?;
    ma.unset_default(&mime_str);
    ma.save()?;
    Ok(())
}

pub fn cmd_add(mime: &str, handler: &str) -> Result<(), Error> {
    let mime = MimeOrExtension::parse(mime).unwrap();
    let mime_str = mime.to_mime_key()?;
    let mut ma = mimeapps::MimeApps::load()?;
    ma.add_default(&mime_str, handler);
    ma.save()?;
    Ok(())
}

pub fn cmd_get(mime: &str, json: bool) -> Result<(), Error> {
    let _ = config::load_or_create(); // ensure config exists? no, handlr only loads when needed
    let mimeobj = MimeOrExtension::parse(mime).unwrap();
    let mime_str = mimeobj.to_mime_key()?;
    let ma = mimeapps::MimeApps::load()?;
    let handler = ma.get_handler(&mime_str).ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
    if json {
        let info = desktop::load_handler(&handler).ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
        let cmd = exec::display_command_with_term(&info)?;
        let mut s = String::from("{\"handler\":");
        crate::exec::json_string(&handler, &mut s);
        s.push_str(",\"name\":");
        crate::exec::json_string(&info.name, &mut s);
        s.push_str(",\"cmd\":");
        crate::exec::json_string(&cmd, &mut s);
        s.push('}');
        println!("{}", s);
    } else {
        println!("{}", handler);
    }
    Ok(())
}

pub fn cmd_launch(mime: &str, args: &[String]) -> Result<(), Error> {
    let mimeobj = MimeOrExtension::parse(mime).unwrap();
    let mime_str = mimeobj.to_mime_key()?;
    let ma = mimeapps::MimeApps::load()?;
    let handler = ma.get_handler(&mime_str).ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
    let normalized: Vec<String> = args.iter().map(|a| crate::url_util::normalize_arg(a)).collect();
    exec::launch(&handler, &normalized)?;
    Ok(())
}
