use crate::common::Error;
use crate::globs;

pub enum MimeOrExtension {
    Mime(String),
    Extension(String),
}

impl MimeOrExtension {
    pub fn parse(s: &str) -> Result<Self, String> {
        if s.starts_with('.') {
            // It's an extension. Look up
            match globs::lookup_extension(s) {
                Some(m) => Ok(MimeOrExtension::Mime(m)),
                None => Err(format!("could not figure out the mime type of '{}'", s)),
            }
        } else {
            // Must be valid mime
            validate_mime(s).map_err(|e| e)?;
            Ok(MimeOrExtension::Mime(s.to_string()))
        }
    }

    pub fn to_mime_key(&self) -> Result<String, Error> {
        match self {
            MimeOrExtension::Mime(m) => Ok(m.clone()),
            MimeOrExtension::Extension(_) => unreachable!(),
        }
    }
}

/// Validate mime type syntax. Returns error messages matching the original format.
/// Examples:
///   "foo" -> "mime parse error: a slash (/) was missing between the type and subtype"
///   "/bar" -> "mime parse error: an invalid token was encountered, 2F at position 0"
fn validate_mime(s: &str) -> Result<(), String> {
    if s.is_empty() {
        return Err(format!("mime parse error: an invalid token was encountered, {} at position 0", "00"));
    }
    // Find slash
    let bytes = s.as_bytes();
    let mut slash_pos = None;
    for (i, &b) in bytes.iter().enumerate() {
        if !is_valid_mime_char(b) && b != b'/' {
            return Err(format!(
                "mime parse error: an invalid token was encountered, {:02X} at position {}",
                b, i
            ));
        }
        if b == b'/' {
            if slash_pos.is_some() {
                return Err(format!(
                    "mime parse error: an invalid token was encountered, {:02X} at position {}",
                    b, i
                ));
            }
            if i == 0 {
                return Err(format!(
                    "mime parse error: an invalid token was encountered, {:02X} at position {}",
                    b, i
                ));
            }
            slash_pos = Some(i);
        }
    }
    match slash_pos {
        None => Err(String::from("mime parse error: a slash (/) was missing between the type and subtype")),
        Some(p) if p == bytes.len() - 1 => Err(format!(
            "mime parse error: an invalid token was encountered, {:02X} at position {}",
            b'/', p
        )),
        _ => Ok(()),
    }
}

fn is_valid_mime_char(b: u8) -> bool {
    // Allow letters, digits, and some symbols used in mime types
    b.is_ascii_alphanumeric()
        || b == b'-'
        || b == b'.'
        || b == b'+'
        || b == b'_'
        || b == b'*'
}
