use std::fs;
use std::path::PathBuf;

pub fn data_dirs() -> Vec<PathBuf> {
    let mut v = Vec::new();
    if let Some(home) = std::env::var_os("XDG_DATA_HOME") {
        v.push(PathBuf::from(home));
    } else if let Some(home) = std::env::var_os("HOME") {
        v.push(PathBuf::from(home).join(".local/share"));
    }
    if let Some(dirs) = std::env::var_os("XDG_DATA_DIRS") {
        for p in std::env::split_paths(&dirs) {
            v.push(p);
        }
    } else {
        v.push(PathBuf::from("/usr/local/share"));
        v.push(PathBuf::from("/usr/share"));
    }
    v
}

pub fn lookup_extension(s: &str) -> Option<String> {
    let ext = s.trim_start_matches('.').to_ascii_lowercase();
    let pattern = format!("*.{}", ext);
    for dir in data_dirs() {
        // prefer globs2 over globs
        for name in &["globs2", "globs"] {
            let path = dir.join("mime").join(name);
            if let Ok(contents) = fs::read_to_string(&path) {
                for line in contents.lines() {
                    let line = line.trim();
                    if line.is_empty() || line.starts_with('#') { continue; }
                    let parts: Vec<&str> = line.split(':').collect();
                    let (mime, glob) = if *name == "globs2" {
                        if parts.len() < 3 { continue; }
                        (parts[1], parts[2])
                    } else {
                        if parts.len() < 2 { continue; }
                        (parts[0], parts[1])
                    };
                    if glob.eq_ignore_ascii_case(&pattern) {
                        return Some(mime.to_string());
                    }
                }
            }
        }
    }
    None
}
