use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use crate::globs;

#[derive(Clone, Debug)]
pub struct Entry {
    pub name: String,
    pub exec: String,
    pub terminal: bool,
    pub mime_types: Vec<String>,
    pub file_name: String,
    pub path: PathBuf,
}

fn application_dirs() -> Vec<PathBuf> {
    globs::data_dirs()
        .into_iter()
        .map(|d| d.join("applications"))
        .collect()
}

/// Read a .desktop file. Returns Some only if parse succeeded (Name= and Exec=).
pub fn read_file(path: &Path) -> Option<Entry> {
    let content = fs::read_to_string(path).ok()?;
    let mut in_entry = false;
    let mut name = None::<String>;
    let mut exec = None::<String>;
    let mut terminal = false;
    let mut mime_types: Vec<String> = Vec::new();
    for line in content.lines() {
        let line = line.trim_end();
        if line.starts_with('[') && line.ends_with(']') {
            in_entry = line == "[Desktop Entry]";
            continue;
        }
        if !in_entry { continue; }
        if let Some(eq) = line.find('=') {
            let key = &line[..eq];
            let val = &line[eq+1..];
            match key {
                "Name" => { name = Some(val.to_string()); }
                "Exec" => { exec = Some(val.to_string()); }
                "Terminal" => { terminal = val.eq_ignore_ascii_case("true"); }
                "MimeType" => {
                    for m in val.split(';') {
                        let t = m.trim();
                        if !t.is_empty() { mime_types.push(t.to_string()); }
                    }
                }
                _ => {}
            }
        }
    }
    let file_name = path.file_name()?.to_string_lossy().into_owned();
    Some(Entry {
        name: name?,
        exec: exec?,
        terminal,
        mime_types,
        file_name,
        path: path.to_path_buf(),
    })
}

/// Load a handler by filename (e.g. "cmus.desktop") searching all application dirs.
pub fn load_handler(handler: &str) -> Option<Entry> {
    for dir in application_dirs() {
        let path = dir.join(handler);
        if path.is_file() {
            if let Some(e) = read_file(&path) {
                return Some(e);
            }
        }
    }
    None
}

/// Check if a handler with given filename is installed and valid.
pub fn exists(handler: &str) -> bool {
    load_handler(handler).is_some()
}

/// Validate handler argument: must be loadable, Name= and Exec= present.
pub fn validate_handler(handler: &str) -> Result<(), String> {
    // First check if a file with this filename exists
    let mut found_file: Option<PathBuf> = None;
    for dir in application_dirs() {
        let path = dir.join(handler);
        if path.is_file() {
            found_file = Some(path);
            break;
        }
    }
    let path = match found_file {
        Some(p) => p,
        None => return Err(format!("no handlers found for '{}'", handler)),
    };
    match read_file(&path) {
        Some(_) => Ok(()),
        None => Err(format!("malformed desktop entry at {}", path.display())),
    }
}

/// Scan system for mime → [handler filenames].
/// This scans all dirs but each unique filename counted once.
pub fn scan_system_mimes() -> BTreeMap<String, Vec<String>> {
    let mut map: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
    for dir in application_dirs() {
        let rd = match fs::read_dir(&dir) {
            Ok(r) => r,
            Err(_) => continue,
        };
        for e in rd.flatten() {
            let p = e.path();
            let name = match p.file_name().and_then(|n| n.to_str()) {
                Some(n) => n.to_string(),
                None => continue,
            };
            if !name.ends_with(".desktop") { continue; }
            if !seen.insert(name.clone()) { continue; }
            let entry = match read_file(&p) {
                Some(e) => e,
                None => continue,
            };
            for m in &entry.mime_types {
                map.entry(m.clone()).or_default().push(entry.file_name.clone());
            }
        }
    }
    map
}
