use std::fs;
use std::path::PathBuf;

pub struct Config {
    pub enable_selector: bool,
    pub selector: String,
}

fn config_dir() -> PathBuf {
    if let Some(c) = std::env::var_os("XDG_CONFIG_HOME") {
        PathBuf::from(c)
    } else if let Some(h) = std::env::var_os("HOME") {
        PathBuf::from(h).join(".config")
    } else {
        PathBuf::from(".")
    }
}

pub fn config_path() -> PathBuf {
    config_dir().join("handlr").join("handlr.toml")
}

impl Config {
    pub fn default() -> Self {
        Config { enable_selector: false, selector: "rofi -dmenu -i -p 'Open With: '".to_string() }
    }
}

/// Load config; if none exists, create default and write to disk.
pub fn load_or_create() -> Config {
    let path = config_path();
    match fs::read_to_string(&path) {
        Ok(c) => parse_toml(&c).unwrap_or_else(Config::default),
        Err(_) => {
            let cfg = Config::default();
            if let Some(parent) = path.parent() {
                let _ = fs::create_dir_all(parent);
            }
            let body = format!("enable_selector = {}\nselector = \"{}\"\n",
                cfg.enable_selector, cfg.selector);
            let _ = fs::write(&path, body);
            cfg
        }
    }
}

fn parse_toml(s: &str) -> Option<Config> {
    let mut enable_selector = false;
    let mut selector = String::from("rofi -dmenu -i -p 'Open With: '");
    for line in s.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        if let Some((k, v)) = line.split_once('=') {
            let k = k.trim();
            let v = v.trim();
            match k {
                "enable_selector" => {
                    enable_selector = v == "true";
                }
                "selector" => {
                    selector = unquote(v);
                }
                _ => {}
            }
        }
    }
    Some(Config { enable_selector, selector })
}

fn unquote(s: &str) -> String {
    let s = s.trim();
    if (s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\'')) {
        s[1..s.len()-1].to_string()
    } else {
        s.to_string()
    }
}
