use unicode_width_simple::display_width;

mod unicode_width_simple {
    /// Return the display width of a string. We support basic ASCII only; for
    /// non-ASCII characters we assume width 1 per codepoint (approximation).
    pub fn display_width(s: &str) -> usize {
        s.chars().count()
    }
}

pub fn print_two_col(rows: &[(String, Vec<String>)]) {
    let formatted: Vec<(String, String)> = rows.iter().map(|(k, vs)| (k.clone(), vs.join(", "))).collect();
    let mut w0 = 0usize;
    let mut w1 = 0usize;
    for (a, b) in &formatted {
        w0 = w0.max(display_width(a));
        w1 = w1.max(display_width(b));
    }
    // Each column is padded with 1 space on each side
    let top = format!("┌{}┬{}┐", "─".repeat(w0 + 2), "─".repeat(w1 + 2));
    let bot = format!("└{}┴{}┘", "─".repeat(w0 + 2), "─".repeat(w1 + 2));
    println!("{}", top);
    for (a, b) in &formatted {
        let pa = " ".repeat(w0 - display_width(a));
        let pb = " ".repeat(w1 - display_width(b));
        println!("│ {}{} │ {}{} │", a, pa, b, pb);
    }
    println!("{}", bot);
}
