use std::process::{Command, Stdio};
use crate::common::Error;
use crate::desktop;
use crate::config;
use crate::mimeapps;

/// Shell-parse an Exec line into tokens, following the Desktop Entry spec rules.
/// Simplified: handle "quoted strings", single-quoted, and backslash escapes.
pub fn shell_parse(s: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut in_double = false;
    let mut has_token = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if in_double {
            if c == '\\' {
                if let Some(&nc) = chars.peek() {
                    if nc == '"' || nc == '\\' || nc == '`' || nc == '$' {
                        chars.next();
                        cur.push(nc);
                        continue;
                    }
                }
                cur.push(c);
            } else if c == '"' {
                in_double = false;
            } else {
                cur.push(c);
            }
        } else {
            if c == '"' {
                in_double = true;
                has_token = true;
            } else if c == '\\' {
                if let Some(&nc) = chars.peek() {
                    chars.next();
                    cur.push(nc);
                    has_token = true;
                }
            } else if c.is_whitespace() {
                if has_token {
                    out.push(std::mem::take(&mut cur));
                    has_token = false;
                }
            } else {
                cur.push(c);
                has_token = true;
            }
        }
    }
    if has_token {
        out.push(cur);
    }
    out
}

/// Returns the display "cmd" form (with terminal wrapping if needed).
pub fn display_command_with_term(info: &desktop::Entry) -> Result<String, Error> {
    let base = display_command_for(&info.exec);
    if info.terminal {
        let ma = mimeapps::MimeApps::load()?;
        let term_handler = ma.get_handler("x-scheme-handler/terminal")
            .ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
        let term_info = desktop::load_handler(&term_handler)
            .ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
        let term_base = display_command_for(&term_info.exec);
        Ok(format!("{} -e {}", term_base, base))
    } else {
        Ok(base)
    }
}

/// Compute display command:
/// - Shell-parse tokens
/// - For each token, replace first occurrence of %f/%F/%u/%U with empty string
/// - Drop tokens that become empty due to substitution
/// - Return "program args.join(\" \")" with a literal space after program even if args is empty
fn display_command_for(exec: &str) -> String {
    let tokens = shell_parse(exec);
    let mut processed: Vec<String> = Vec::new();
    for tok in tokens {
        let (new, was_replaced) = strip_first_path_field(&tok);
        if was_replaced && new.is_empty() { continue; }
        processed.push(new);
    }
    if processed.is_empty() {
        return String::new();
    }
    let program = processed.remove(0);
    let args = processed.join(" ");
    format!("{} {}", program, args)
}

/// Replace the first occurrence of %f|%F|%u|%U with empty string.
/// Return (new, true) if replacement occurred, else (tok, false).
fn strip_first_path_field(tok: &str) -> (String, bool) {
    let bytes = tok.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() {
        if bytes[i] == b'%' {
            let c = bytes[i+1];
            if c == b'f' || c == b'F' || c == b'u' || c == b'U' {
                let mut s = String::with_capacity(tok.len() - 2);
                s.push_str(&tok[..i]);
                s.push_str(&tok[i+2..]);
                return (s, true);
            }
        }
        i += 1;
    }
    (tok.to_string(), false)
}

/// Replace the first occurrence of %f|%F|%u|%U with a given string.
/// Return (new, true) if replaced.
fn replace_first_path_field(tok: &str, with: &str) -> (String, bool) {
    let bytes = tok.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() {
        if bytes[i] == b'%' {
            let c = bytes[i+1];
            if c == b'f' || c == b'F' || c == b'u' || c == b'U' {
                let mut s = String::with_capacity(tok.len() + with.len());
                s.push_str(&tok[..i]);
                s.push_str(with);
                s.push_str(&tok[i+2..]);
                return (s, true);
            }
        }
        i += 1;
    }
    (tok.to_string(), false)
}

fn is_exact_path_field(tok: &str) -> bool {
    matches!(tok, "%f" | "%F" | "%u" | "%U")
}

/// Expand Exec and launch the handler.
pub fn launch(handler: &str, paths: &[String]) -> Result<(), Error> {
    let info = desktop::load_handler(handler)
        .ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
    // Build args (for the actual execution).
    let mut argv = expand_command(&info.exec, paths);
    if info.terminal {
        let ma = mimeapps::MimeApps::load()?;
        let term_handler = ma.get_handler("x-scheme-handler/terminal")
            .ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
        let term_info = desktop::load_handler(&term_handler)
            .ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?;
        // Expand terminal exec with no paths, append -e, then append argv
        let mut term_argv = expand_command(&term_info.exec, &[]);
        term_argv.push("-e".to_string());
        term_argv.extend(argv);
        argv = term_argv;
    }
    if argv.is_empty() {
        return Err(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)));
    }
    let mut cmd = Command::new(&argv[0]);
    cmd.args(&argv[1..]);
    cmd.stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null());
    cmd.spawn()?;
    Ok(())
}

/// Expand Exec with paths:
/// - Shell-parse tokens
/// - For each token:
///   - If exactly %f/%F/%u/%U: replace with N tokens (one per path)
///   - Else if contains field code: replace first occurrence with paths joined by " "
///   - Else: keep as-is
/// - If no field code was replaced and paths is non-empty, append all paths at end
fn expand_command(exec: &str, paths: &[String]) -> Vec<String> {
    let tokens = shell_parse(exec);
    let mut result: Vec<String> = Vec::new();
    let mut replaced = false;
    for tok in tokens {
        if is_exact_path_field(&tok) {
            for p in paths {
                result.push(p.clone());
            }
            replaced = true;
        } else {
            let joined = paths.join(" ");
            let (new, did) = replace_first_path_field(&tok, &joined);
            if did { replaced = true; }
            result.push(new);
        }
    }
    if !replaced {
        for p in paths {
            result.push(p.clone());
        }
    }
    // Drop empty tokens that are artifacts of removed field codes? We're not stripping here.
    result
