    // If it looks like a URL with scheme, treat as URL (unless scheme is "file")
    if let Some((scheme, _)) = split_scheme(p) {
        let scheme_l = scheme.to_ascii_lowercase();
        if scheme_l != "file" {
            let norm = url_util::normalize_arg(p);
            return Ok((format!("x-scheme-handler/{}", scheme_l), norm));
        }
    }
    // Otherwise treat as file path. Must exist.
    let path = Path::new(p);
    if !path.exists() {
        return Err(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)));
    }
    // Look up mime from extension
    let mime = if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
        let key = format!(".{}", ext);
        globs::lookup_extension(&key).ok_or(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)))?
    } else {
        return Err(Error::Io(std::io::Error::from(std::io::ErrorKind::NotFound)));
    };
    Ok((mime, p.to_string()))
}

fn split_scheme(s: &str) -> Option<(&str, &str)> {
    let bytes = s.as_bytes();
    if bytes.is_empty() { return None; }
    if !bytes[0].is_ascii_alphabetic() { return None; }
    for (i, &b) in bytes.iter().enumerate() {
        if i == 0 { continue; }
        if b == b':' {
            // Must have at least one more char (scheme:X form requires)
            if i < 1 { return None; }
            return Some((&s[..i], &s[i+1..]));
        }
        if !(b.is_ascii_alphanumeric() || b == b'+' || b == b'-' || b == b'.') {
            return None;
        }
    }
    None
}
