use std::fmt;
use std::io;

#[derive(Debug)]
pub enum Error {
    Io(io::Error),
    NotFound,
    MalformedDesktopEntry(String),
    Custom(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Io(e) => write!(f, "Io({:?})", e),
            Error::NotFound => write!(f, "NotFound"),
            Error::MalformedDesktopEntry(p) => write!(f, "malformed desktop entry at {}", p),
            Error::Custom(s) => write!(f, "{}", s),
        }
    }
}

impl From<io::Error> for Error {
    fn from(e: io::Error) -> Self {
        Error::Io(e)
    }
}

/// Construct a "NotFound" (errno=2) error that matches the original output format.
pub fn not_found() -> Error {
    Error::Io(io::Error::from_raw_os_error(2))
}
