use crate::config;

/// Pick a handler using the selector if multiple candidates and enabled.
pub fn select_handler(candidates: &[String]) -> Result<String, Error> {
    if candidates.len() <= 1 {
        return candidates.first().cloned().ok_or(crate::common::not_found());
    }
    let cfg = config::load_or_create();
    if !cfg.enable_selector {
        return Ok(candidates[0].clone());
    }
    // Gather Names for each candidate
    let mut entries = Vec::new();
    for h in candidates {
        if let Some(e) = desktop::load_handler(h) {
            entries.push((e.name.clone(), h.clone()));
        }
    }
    if entries.is_empty() { return Err(crate::common::not_found()); }
    // Build stdin: "name1\nname2" (no trailing newline)
    let stdin_body = entries.iter().map(|(n, _)| n.clone()).collect::<Vec<_>>().join("\n");
    // Run selector
    use std::io::Write;
    let mut sel_tokens = shell_parse(&cfg.selector);
    if sel_tokens.is_empty() { return Ok(candidates[0].clone()); }
    let prog = sel_tokens.remove(0);
    let mut child = Command::new(&prog)
        .args(&sel_tokens)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()?;
    if let Some(stdin) = child.stdin.as_mut() {
        stdin.write_all(stdin_body.as_bytes())?;
    }
    let out = child.wait_with_output()?;
    let chosen = String::from_utf8_lossy(&out.stdout).trim().to_string();
    for (name, h) in &entries {
        if name == &chosen {
            return Ok(h.clone());
        }
    }
    // If no match, panic like the original? Or fall back to first.
    Err(crate::common::Error::Custom(format!("no match for selector output: {}", chosen)))
}
EOF
