# Modify mimeapps.rs to add get_handlers that returns all valid candidates
cat > src/mimeapps.rs << 'EOF'
use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;
use crate::common::Error;
use crate::desktop;

pub struct MimeApps {
    pub default_apps: Vec<(String, Vec<String>)>,
    pub added_associations: Vec<(String, Vec<String>)>,
}

fn config_path() -> PathBuf {
    if let Some(c) = std::env::var_os("XDG_CONFIG_HOME") {
        PathBuf::from(c).join("mimeapps.list")
    } else if let Some(h) = std::env::var_os("HOME") {
        PathBuf::from(h).join(".config").join("mimeapps.list")
    } else {
        PathBuf::from("mimeapps.list")
    }
}

impl MimeApps {
    pub fn load() -> Result<Self, Error> {
        let path = config_path();
        let contents = match fs::read_to_string(&path) {
            Ok(c) => c,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => String::new(),
            Err(e) => return Err(Error::Io(e)),
        };
        let mut default_apps: Vec<(String, Vec<String>)> = Vec::new();
        let mut added_associations: Vec<(String, Vec<String>)> = Vec::new();
        let mut section = String::new();
        for line in contents.lines() {
            let l = line.trim_end();
            if l.starts_with('[') && l.ends_with(']') {
                section = l[1..l.len()-1].to_string();
                continue;
            }
            if l.is_empty() { continue; }
            let eq = match l.find('=') { Some(x) => x, None => continue };
            let key = l[..eq].to_string();
            if !is_valid_mime_key(&key) { continue; }
            let value = &l[eq+1..];
            let mut vals: Vec<String> = Vec::new();
            for v in value.split(';') {
                let s = v.trim();
                if !s.is_empty() { vals.push(s.to_string()); }
            }
            match section.as_str() {
                "Default Applications" => default_apps.push((key, vals)),
                "Added Associations" => added_associations.push((key, vals)),
                _ => {}
            }
        }
        default_apps.sort_by(|a, b| a.0.cmp(&b.0));
        added_associations.sort_by(|a, b| a.0.cmp(&b.0));
        Ok(MimeApps { default_apps, added_associations })
    }

    pub fn save(&self) -> Result<(), Error> {
        let path = config_path();
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }
        let mut out = String::new();
        out.push_str("[Added Associations]\n");
        let mut added: BTreeMap<String, Vec<String>> = BTreeMap::new();
        for (k, v) in &self.added_associations {
            let kept: Vec<String> = v.iter().filter(|h| desktop::exists(h)).cloned().collect();
            if !kept.is_empty() { added.insert(k.clone(), kept); }
        }
        for (k, v) in &added {
            out.push_str(&format!("{}={};\n", k, v.join(";")));
        }
        out.push('\n');
        out.push_str("[Default Applications]\n");
        let mut defaults: BTreeMap<String, Vec<String>> = BTreeMap::new();
        for (k, v) in &self.default_apps {
            let kept: Vec<String> = v.iter().filter(|h| desktop::exists(h)).cloned().collect();
            if !kept.is_empty() { defaults.insert(k.clone(), kept); }
        }
        for (k, v) in &defaults {
            out.push_str(&format!("{}={};\n", k, v.join(";")));
        }
        fs::write(path, out)?;
        Ok(())
    }

    pub fn set_default(&mut self, mime: &str, handler: &str) {
        let handler = handler.to_string();
        if let Some(entry) = self.default_apps.iter_mut().find(|(k, _)| k == mime) {
            entry.1 = vec![handler];
        } else {
            self.default_apps.push((mime.to_string(), vec![handler]));
        }
    }

    pub fn add_default(&mut self, mime: &str, handler: &str) {
        let handler = handler.to_string();
        if let Some(entry) = self.default_apps.iter_mut().find(|(k, _)| k == mime) {
            entry.1.push(handler);
        } else {
            self.default_apps.push((mime.to_string(), vec![handler]));
        }
    }

    pub fn unset_default(&mut self, mime: &str) {
        self.default_apps.retain(|(k, _)| k != mime);
    }

    /// Get the first valid handler for a mime type (used by `get` and fallback).
    pub fn get_handler(&self, mime: &str) -> Option<String> {
        self.get_handlers(mime).into_iter().next()
    }

    /// Get all valid candidate handlers in precedence order.
    /// For launch, the selector may pick among them.
    pub fn get_handlers(&self, mime: &str) -> Vec<String> {
        // 1. Default Applications exact match
        if let Some((_, v)) = self.default_apps.iter().find(|(k, _)| k == mime) {
            let valid: Vec<String> = v.iter().filter(|h| desktop::exists(h)).cloned().collect();
            if !valid.is_empty() { return valid; }
        }
        // 2. Default Applications wildcard (type/*)
        if let Some(slash) = mime.find('/') {
            let t = &mime[..slash];
            let wildcard = format!("{}/*", t);
            if let Some((_, v)) = self.default_apps.iter().find(|(k, _)| k == &wildcard) {
                let valid: Vec<String> = v.iter().filter(|h| desktop::exists(h)).cloned().collect();
                if !valid.is_empty() { return valid; }
            }
        }
        // 3. Added Associations
        if let Some((_, v)) = self.added_associations.iter().find(|(k, _)| k == mime) {
            let valid: Vec<String> = v.iter().filter(|h| desktop::exists(h)).cloned().collect();
            if !valid.is_empty() { return valid; }
        }
        // 4. System apps (from MimeType= entries)
        let sys = desktop::scan_system_mimes();
        if let Some(v) = sys.get(mime) {
            let valid: Vec<String> = v.iter().filter(|h| desktop::exists(h)).cloned().collect();
            if !valid.is_empty() { return valid; }
        }
        Vec::new()
    }
}

fn is_valid_mime_key(s: &str) -> bool {
    let mut slashes = 0;
    for c in s.chars() {
        if c == '/' { slashes += 1; }
        else if !(c.is_ascii_alphanumeric() || "-_+.*".contains(c)) {
            return false;
        }
    }
    slashes == 1
}
