use crate::common::Error;
use crate::globs;

pub struct MimeOrExtension {
    mime: String,
}

impl MimeOrExtension {
    pub fn parse(s: &str) -> Result<Self, String> {
        if s.starts_with('.') {
            match globs::lookup_extension(s) {
                Some(m) => Ok(MimeOrExtension { mime: m }),
                None => Err(format!("could not figure out the mime type of '{}'", s)),
            }
        } else {
            validate_mime(s)?;
            Ok(MimeOrExtension { mime: s.to_string() })
        }
    }

    pub fn to_mime_key(&self) -> Result<String, Error> {
        Ok(self.mime.clone())
    }
}

fn validate_mime(s: &str) -> Result<(), String> {
    if s.is_empty() {
        return Err("mime parse error: a slash (/) was missing between the type and subtype".to_string());
    }
    let bytes = s.as_bytes();
    let mut slash_pos = None;
    for (i, &b) in bytes.iter().enumerate() {
        if b == b'/' {
            if slash_pos.is_some() {
                return Err(format!(
                    "mime parse error: an invalid token was encountered, {:02X} at position {}",
                    b, i
                ));
            }
            if i == 0 {
                return Err(format!(
                    "mime parse error: an invalid token was encountered, {:02X} at position {}",
                    b, i
                ));
            }
            slash_pos = Some(i);
        } else if !is_valid_mime_char(b) {
            return Err(format!(
                "mime parse error: an invalid token was encountered, {:02X} at position {}",
                b, i
            ));
        }
    }
    match slash_pos {
        None => Err("mime parse error: a slash (/) was missing between the type and subtype".to_string()),
        Some(p) if p == bytes.len() - 1 => Err(format!(
            "mime parse error: an invalid token was encountered, {:02X} at position {}",
            b'/', p
        )),
        _ => Ok(()),
    }
}

fn is_valid_mime_char(b: u8) -> bool {
    b.is_ascii_alphanumeric()
        || b == b'-'
        || b == b'.'
        || b == b'+'
        || b == b'_'
        || b == b'*'
}
